:root {
  --green-dark: #2d6a4f;
  --green-mid: #52b788;
  --green-light: #d8f3dc;
  --green-pale: #f0faf2;
  --accent-yellow: #f4a261;
  --accent-red: #e63946;
  --text-primary: #1b2e22;
  --text-secondary: #4a7c59;
  --text-muted: #8aab94;
  --white: #ffffff;
  --border: #b7e4c7;
  --star-active: #f4a261;
  --star-dim: #c8dfd0;
  --price-old: #a0b8a8;
  --badge-bg: #2d6a4f;
  --badge-text: #ffffff;
  --tag-bg: #d8f3dc;
  --tag-text: #2d6a4f;
}

.catalog-card {
  background: var(--white);
  border: 2px solid var(--border);
  border-radius: 16px;
  padding: 20px;
  width: 480px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.season-tag {
  background: var(--tag-bg);
  color: var(--tag-text);
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.stock-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.04em;
}

.plant-showcase {
  display: flex;
  align-items: center;
  gap: 16px;
  background: var(--green-pale);
  border-radius: 12px;
  padding: 14px 16px;
  border: 1px solid var(--border);
}

.plant-icon {
  font-size: 52px;
  line-height: 1;
  flex-shrink: 0;
}

.plant-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.plant-name {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.plant-latin {
  font-size: 13px;
  color: var(--text-secondary);
  font-style: italic;
  margin: 0;
}

.rating-row {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-top: 4px;
}

.star {
  font-size: 14px;
  color: var(--star-active);
}

.star.dim {
  color: var(--star-dim);
}

.review-count {
  font-size: 12px;
  color: var(--text-muted);
  margin-left: 6px;
}

.care-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.care-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  background: var(--green-pale);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 6px;
}

.care-icon {
  font-size: 18px;
  line-height: 1;
}

.care-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.care-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 4px;
  border-top: 1px solid var(--border);
}

.price-block {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.price-old {
  font-size: 14px;
  color: var(--price-old);
  text-decoration: line-through;
}

.price-now {
  font-size: 24px;
  font-weight: 800;
  color: var(--green-dark);
}

.add-btn {
  background: var(--green-mid);
  color: var(--white);
  border: none;
  border-radius: 10px;
  padding: 10px 22px;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  letter-spacing: 0.02em;
}
